import { Children, useRef, useState } from "react";
import type { ReactNode } from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import type { LayoutChangeEvent, NativeScrollEvent, NativeSyntheticEvent, StyleProp, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface CarouselProps extends Omit<ViewProps, "children"> {
  label: string;
  children: ReactNode;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Share of the width each slide takes, so the next one peeks in. */
  slideSize?: number;
  slideLabel?: (index: number, count: number) => string;
  /** Extend the inner, named parts of the carousel: slide, dots or dot. The React Native counterpart of `classNames`. */
  styles?: {
    slide?: StyleProp<ViewStyle>;
    dots?: StyleProp<ViewStyle>;
    dot?: StyleProp<ViewStyle>;
  };
}

/** Slides snap into place as you scroll. Pass the children as the slides. */
export function Carousel({ label, children, index, defaultIndex = 0, onIndexChange, slideSize = 0.72, slideLabel = (at, count) => `Slide ${at + 1} of ${count}`, style, styles: parts, ...props }: CarouselProps) {
  const tokens = useTokens();
  const slides = Children.toArray(children);
  const [width, setWidth] = useState(0);
  const [internal, setInternal] = useState(defaultIndex);
  const scroller = useRef<ScrollView>(null);
  const current = index ?? internal;
  const slide = width * slideSize;
  const gap = 12;

  function goTo(next: number, animated = true) {
    const clamped = Math.max(0, Math.min(slides.length - 1, next));
    scroller.current?.scrollTo({ x: clamped * (slide + gap), animated });
    if (index === undefined) setInternal(clamped);
    onIndexChange?.(clamped);
  }

  return (
    <View {...props} accessibilityRole="adjustable" accessibilityLabel={label} accessibilityActions={[{ name: "increment" }, { name: "decrement" }]} onAccessibilityAction={({ nativeEvent }) => goTo(current + (nativeEvent.actionName === "increment" ? 1 : -1))} style={[{ alignSelf: "stretch", gap: metrics.space[3] }, style]}>
      <ScrollView
        ref={scroller}
        horizontal
        showsHorizontalScrollIndicator={false}
        snapToInterval={slide + gap}
        decelerationRate="fast"
        contentOffset={{ x: current * (slide + gap), y: 0 }}
        onLayout={(event: LayoutChangeEvent) => setWidth(event.nativeEvent.layout.width)}
        onMomentumScrollEnd={(event: NativeSyntheticEvent<NativeScrollEvent>) => {
          const next = Math.round(event.nativeEvent.contentOffset.x / Math.max(1, slide + gap));
          if (index === undefined) setInternal(next);
          onIndexChange?.(next);
        }}
        contentContainerStyle={{ gap }}
      >
        {slides.map((child, at) => (
          <View key={at} accessible accessibilityLabel={slideLabel(at, slides.length)} style={[{ width: slide || undefined }, parts?.slide]}>
            {child}
          </View>
        ))}
      </ScrollView>
      <View style={[local.dots, parts?.dots]}>
        {slides.map((_, at) => (
          <Pressable key={at} accessibilityRole="button" accessibilityLabel={slideLabel(at, slides.length)} accessibilityState={{ selected: at === current }} hitSlop={6} onPress={() => goTo(at)} style={[local.dot, { backgroundColor: at === current ? tokens.foreground : tokens.borderStrong }, parts?.dot]} />
        ))}
      </View>
      <Text style={{ color: tokens.textMuted, fontSize: metrics.text.xs, textAlign: "center" }}>{current + 1} / {slides.length}</Text>
    </View>
  );
}

const local = StyleSheet.create({
  dots: { flexDirection: "row", justifyContent: "center", gap: 8 },
  dot: { width: 8, height: 8, borderRadius: 4 },
});

export default Carousel;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
